import{_ as l,a0 as g,w as o,s as r,ao as p,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Sysget：給主流的包管理器加個前端 | LCTT x X-CMD","titleTemplate":false,"description":"Sysget：給主流的包管理器加個前端 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Sysget：給主流的包管理器加個前端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Sysget：給主流的包管理器加個前端 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181011 A Front-end For Popular Package Managers","title":"Sysget：給主流的包管理器加個前端","tag":"201810","desc":""},"relativePath":"201810/20181011 A Front-end For Popular Package Managers.md","filePath":"[post].md"}'),d={name:"201810/20181011 A Front-end For Popular Package Managers.md"};function h(u,s,c,k,b,y){const e=g("Link");return o(),r("div",null,[s[18]||(s[18]=p('<h1 id="sysget-給主流的包管理器加個前端" tabindex="-1">Sysget：給主流的包管理器加個前端 <a class="header-anchor" href="#sysget-給主流的包管理器加個前端" aria-label="Permalink to “Sysget：給主流的包管理器加個前端”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/sysget-720x340.png" alt=""></p><p>你是一個喜歡每隔幾天嘗試 Linux 操作系統的新發行版的發行版收割機嗎？如果是這樣，我有一些東西對你有用。 嘗試 Sysget，這是一個類 Unix 操作系統中的流行軟件包管理器的前端。 你不需要學習每個包管理器來執行基本的操作，例如安裝、更新、升級和刪除包。 你只需要對每個運行在類 Unix 操作系統上的包管理器記住一種語法即可。 Sysget 是包管理器的包裝腳本，它是用 C++ 編寫的。 源代碼可在 GitHub 上免費獲得。</p><p>使用 Sysget，你可以執行各種基本的包管理操作，包括：</p><ul><li>安裝包，</li><li>更新包，</li><li>升級包，</li><li>搜索包，</li><li>刪除包，</li><li>刪除棄用包，</li><li>更新資料庫，</li><li>升級系統，</li><li>清除包管理器緩存。</li></ul><p><strong>給 Linux 學習者的一個重要提示：</strong></p><p>Sysget 不會取代軟件包管理器，絕對不適合所有人。如果你是經常切換到新 Linux 操作系統的新手，Sysget 可能會有所幫助。當在不同的 Linux 發行版中使用不同的軟件包管理器時，就必須學習安裝、更新、升級、搜索和刪除軟件包的新命令，這時 Sysget 就是幫助<ruby>發行版收割機<rt>distro hopper</rt></ruby>（或新 Linux 用户）的包裝腳本。</p><p>如果你是 Linux 管理員或想要學習 Linux 深層的愛好者，你應該堅持使用你的發行版的軟件包管理器並學習如何使用它。</p><h3 id="安裝-sysget" tabindex="-1">安裝 Sysget <a class="header-anchor" href="#安裝-sysget" aria-label="Permalink to “安裝 Sysget”">​</a></h3>',9)),n("p",null,[s[1]||(s[1]=a("安裝 Sysget 很簡單。 轉到",-1)),i(e,{href:"https://github.com/emilengler/sysget/releases"},{default:t(()=>[...s[0]||(s[0]=[a("發佈頁面",-1)])]),_:1}),s[2]||(s[2]=a("並下載最新的 Sysget 二進制文件並按如下所示進行安裝。 在編寫本指南時，Sysget 最新版本為1.2。",-1))]),s[19]||(s[19]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo wget -O /usr/local/bin/sysget https://github.com/emilengler/sysget/releases/download/v1.2/sysget</span></span>
<span class="line"><span>$ sudo mkdir -p /usr/local/share/sysget</span></span>
<span class="line"><span>$ sudo chmod a+x /usr/local/bin/sysget</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>Sysget 命令與 APT 包管理器大致相同，因此它應該適合新手使用。</p><p>當你第一次運行 Sysget 時，系統會要求你選擇要使用的包管理器。 由於我在 Ubuntu，我選擇了 apt-get。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/sysget-1.png" alt=""></p><p>你必須根據正在運行的發行版選擇正確的包管理器。 例如，如果你使用的是 Arch Linux，請選擇 pacman。 對於 CentOS，請選擇 yum。 對於 FreeBSD，請選擇 pkg。 當前支持的包管理器列表是：</p><ol><li>apt-get (Debian)</li><li>xbps (Void)</li><li>dnf (Fedora)</li><li>yum (Enterprise Linux/Legacy Fedora)</li><li>zypper (OpenSUSE)</li><li>eopkg (Solus)</li><li>pacman (Arch)</li><li>emerge (Gentoo)</li><li>pkg (FreeBSD)</li><li>chromebrew (ChromeOS)</li><li>homebrew (Mac OS)</li><li>nix (Nix OS)</li><li>snap (Independent)</li><li>npm (Javascript, Global)</li></ol><p>如果你分配了錯誤的包管理器，則可以使用以下命令設置新的包管理器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget set yum</span></span>
<span class="line"><span>Package manager changed to yum</span></span></code></pre></div><p>只需確保你選擇了本地包管理器。</p><p>現在，你可以像使用本機包管理器一樣執行包管理操作。</p><p>要安裝軟件包，例如 Emacs，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget install emacs</span></span></code></pre></div><p>上面的命令將調用本機包管理器（在我的例子中是 “apt-get”）並安裝給定的包。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Install-package-using-Sysget.png" alt=""></p><p>同樣，要刪除包，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget remove emacs</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Remove-package-using-Sysget.png" alt=""></p><p>更新軟件倉庫（資料庫）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget update</span></span></code></pre></div><p>搜索特定包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget search emacs</span></span></code></pre></div><p>升級單個包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget upgrade emacs</span></span></code></pre></div><p>升級所有包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget upgrade</span></span></code></pre></div><p>移除廢棄的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget autoremove</span></span></code></pre></div><p>清理包管理器的緩存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget clean</span></span></code></pre></div><p>有關更多詳細信息，請參閲幫助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysget help</span></span>
<span class="line"><span>Help of sysget</span></span>
<span class="line"><span>sysget [OPTION] [ARGUMENT]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>search [query] search for a package in the resporitories</span></span>
<span class="line"><span>install [package] install a package from the repos</span></span>
<span class="line"><span>remove [package] removes a package</span></span>
<span class="line"><span>autoremove removes not needed packages (orphans)</span></span>
<span class="line"><span>update update the database</span></span>
<span class="line"><span>upgrade do a system upgrade</span></span>
<span class="line"><span>upgrade [package] upgrade a specific package</span></span>
<span class="line"><span>clean clean the download cache</span></span>
<span class="line"><span>set [NEW MANAGER] set a new package manager</span></span></code></pre></div><p>請記住，不同 Linux 發行版中的所有包管理器的 Sysget 語法都是相同的。 你不需要記住每個包管理器的命令。</p><p>同樣，我必須告訴你 Sysget 不是包管理器的替代品。 它只是類 Unix 系統中流行的包管理器的包裝器，它只執行基本的包管理操作。</p><p>Sysget 對於不想去學習不同包管理器的新命令的新手和發行版收割機用户可能有些用處。 如果你有興趣，試一試，看看它是否有幫助。</p><p>而且，這就是本次所有的內容了。 更多幹貨即將到來。 敬請關注！</p><p>祝快樂！</p><hr>`,38)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"https://www.ostechnix.com/sysget-a-front-end-for-popular-package-managers/"},{default:t(()=>[...s[3]||(s[3]=[a("https://www.ostechnix.com/sysget-a-front-end-for-popular-package-managers/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[5]||(s[5]=[a("SK",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),i(e,{href:"https://github.com/Flowsnow"},{default:t(()=>[...s[7]||(s[7]=[a("Flowsnow",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=l(d,[["render",h]]);export{x as __pageData,C as default};
